// WeaponConfig is a FIXED-CLASS root (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4): its file is form 3,
// so this Load reads that form through WeaponConfigFixedLoad and refuses a form-1
// file as previous_form, never reading a value.
// WeaponConfigLoad is the read (mas-bandwidth/schema docs/SPEC-TABLES.md §4, §6.5): it returns the whole value, or
// refuses with value at its defaults and false. A supplied report receives this
// read's report, and on a refusal report.Err() is the typed reason. The open
// checks every condition the wire alone decides; the body read checks this
// declaration's (tla/ReadOrder.tla, OneVerdict).
func WeaponConfigLoad(value *WeaponConfig, data []byte, report *TableReport) bool {
	read := report
	if read == nil {
		read = &TableReport{}
	} else {
		*read = TableReport{}
	}
	if len(data) > 0 && data[0] == 1 {
		read.Refuse(TableRefusePreviousForm, "")
		WeaponConfigReset(value)
		return false
	}
	if len(data) > 0 && data[0] == TableFixedForm {
		var fixed [1]WeaponConfig
		if WeaponConfigFixedLoad(fixed[:], data, WeaponConfigFixedReadPlan, read) != 1 {
			WeaponConfigReset(value)
			return false
		}
		*value = fixed[0]
		return true
	}
	r, verdict := tableOpenChecked(data, read)
	tableFirstUseCount(read, 2)
	if verdict != TableOpenOk || !WeaponConfigLoadBody(&r, value) || r.Offset != int64(len(r.Buffer)) || !tableFirstUseWhole(read, uint64(len(r.Ids)/8)) || read.Refused() {
		if verdict == TableOpenOk {
			read.Verdict = TableOpenDamaged
		}
		tableRefused(read)
		WeaponConfigReset(value)
		return false
	}
	return true
}

// WeaponConfigReadStrict is WeaponConfigLoad under a second spelling (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): the value, or the typed reason.
func WeaponConfigReadStrict(wire []byte) (*WeaponConfig, error) {
	value := &WeaponConfig{}
	var report TableReport
	if !WeaponConfigLoad(value, wire, &report) {
		return nil, report.Err()
	}
	return value, nil
}

